question.solution:
class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError('金额必须大于 0')
        self.balance += amount
        return self.balance

    def withdraw(self, amount):
        if amount <= 0 or amount > self.balance:
            raise ValueError('余额不足')
        self.balance -= amount
        return self.balance

    def __str__(self):
        return f'{self.owner} 的账户：余额 {self.balance} 元'

acc = Account('小明')
acc.deposit(200)
acc.withdraw(50)
print(acc)
print(acc.balance)

checks:
try:
    acc.withdraw(9999)
    assert False, '余额不足时应抛 ValueError'
except ValueError as e:
    assert '余额不足' in str(e), '余额不足的报错信息不对'

try:
    acc.deposit(0)
    assert False, '存入 0 元时应抛 ValueError'
except ValueError:
    pass
